"""Build a standalone local planning board; no server or game data mutation."""
import html
import json
from pathlib import Path

B=Path(__file__).resolve().parent
read=lambda name:json.loads((B/name).read_text(encoding='utf-8'))
C,S,D=read('cast.json'),read('story.json'),read('design.json')
e=lambda value:html.escape(str(value))
paragraphs=lambda values:''.join(f'<p>{e(x)}</p>' for x in values)
species={x['id']:x['name'] for x in C['species']}
jobs={x['id']:x['name'] for x in C['jobs']}

cards=''
for i,c in enumerate(C['coreCast']):
    kind=species.get(c.get('speciesId'),'마법 구조물')
    job=jobs.get(c.get('jobId'),'골렘' if c['id']=='dolmun' else '최종 보스')
    cards+=f'''<article class="card" id="cast-{c['id']}"><span class="number">{i+1:02}</span><h3 class="name">{e(c['name'])}</h3><span class="pill">{kind}</span><span class="pill">{job}</span><p><b>{e(c['role'])}</b></p><p>{e(c['oneLine'])}</p><dl><dt>이번 이야기에서</dt><dd>{e(c['motivation'])}</dd><dt>외형과 장비</dt><dd>{e(c['silhouette'])}<br>{e(c['equipment'])}</dd><dt>성격</dt><dd>{e(c['personality'])}</dd></dl></article>'''

taxonomy=''.join(f'<tr><td>{e(x["name"])}</td><td>{e(x["visual"])}</td><td>{e(x["scope"])}</td></tr>' for x in C['species'])
job_text=' · '.join(e(x['name']) for x in C['jobs'])
tabs='';zones=''
for i,z in enumerate(S['zones']):
    zid=z['id'];start,end=z['range']
    tabs+=f'<button type="button" id="tab-{zid}" data-zone="{zid}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="zone-{zid}" tabindex="{0 if i==0 else -1}">{start}–{end} · {e(z["name"])}</button>'
    talk=''.join(f'<p><b>{e(x["speaker"])}</b><span>{e(x["text"])}</span></p>' for x in z['bossDialogue'])
    zones+=f'''<article id="zone-{zid}" class="route-panel" role="tabpanel" aria-labelledby="tab-{zid}" {'' if i==0 else 'hidden'}><div class="zone-picture" style="--pos:{i*25}%" role="img" aria-label="{e(z['name'])} 배경 분위기 초안"></div><div class="zone-body"><p class="route-label">STAGE {start}–{end}</p><h3>{e(z['name'])}</h3><p><b>{e(z['purpose'])}</b></p><p>{e(z['landscape'])}</p><dl><dt>이곳에 온 이유</dt><dd>{e(z['entryReason'])}</dd><dt>Stage {z['miniboss']['stage']}</dt><dd>{e(z['miniboss']['name'])} · 중간 보스</dd><dt>Stage {z['boss']['stage']}</dt><dd>{e(z['boss']['name'])} · {e(z['boss']['nature'])}</dd><dt>다음 목적지</dt><dd>{e(z['exitReason'])}</dd></dl><div class="dialogue">{talk}</div><p class="small">{e(z['boss']['defeat'])}</p></div></article>'''

def stage_table(rows,full=False):
    content=''
    role={'normal':'일반','miniboss':'중간 보스','boss':'보스'}
    for x in rows:
        content+=f'<tr><td>{x["stage"]}</td><td><b>{e(x["name"])}</b><br>{role.get(x["role"],e(x["role"]))}</td><td>{e(x["pattern"])}</td><td>{e(x["artReuse"])}'+(f'<br><span class="small">{e(x["storyBeat"])}</span>' if x['storyBeat'] else '')+'</td></tr>'
    return '<div class="scroll"><table><thead><tr><th>Stage</th><th>상대</th><th>전투에서 읽을 동작</th><th>제작·이야기 연결</th></tr></thead><tbody>'+content+'</tbody></table></div>'

more=''
for z in S['zones'][1:]:
    rows=[x for x in S['stages'] if x['zoneId']==z['id']]
    more+=f'<details><summary>Stage {z["range"][0]}–{z["range"][1]} · {e(z["name"])} 편성 10종</summary>{stage_table(rows,True)}</details>'
renames=''.join(f'<tr><td>{e(x["old"])}</td><td><b>{e(x["new"])}</b></td><td>{e(x["meaning"])}</td></tr>' for x in D['naming'])
palette=''.join(f'<div><span style="background:{x["color"]}"></span><b>{e(x["name"])}</b><code>{x["color"]}</code></div>' for x in D['palette'])

template='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>용 잡으러 갑니다 · 판타지 개편 기획</title><link rel="stylesheet" href="board.css"><script src="board.js" defer></script></head><body>
<header><div class="nav"><a class="brand" href="#top">용 잡으러 갑니다</a><nav aria-label="판타지 기획 목차"><a href="Adventure-v6/index.html">최신 변경·동료 스킬</a><a href="#adventure-v5">동료·회복력 개정</a><a href="#unity-build">현재 제작</a><a href="#character-skills">전용 스킬</a><a href="#dialogue-v4">만남·대화</a><a href="#game-identity">핵심 재미</a><a href="#stage-ground">지면·모션</a><a href="#attack-audio">공격음</a><a href="#battle-preview">전투 시안</a><a href="#pixel-ui">도트 UI</a><a href="#monsters">몬스터 도트</a><a href="#cast">캐릭터</a><a href="#story">스토리</a><a href="#route">여정</a><a href="#stages">스테이지</a><a href="#design">디자인</a></nav></div></header>
<main>__UNITY_V6__<details><summary>이전 v0.9.4 제작 기록</summary>__UNITY_V5____ADVENTURE_V5__</details><section class="hero" id="top"><div><span class="status">2026-10-25 · 독립 스킬·동료 성장·HP 잔상 v0.9.6 적용</span><h1>작은 모험가,<br>이번 의뢰는<br><span style="color:var(--red)">커다란 용.</span></h1><p class="eyebrow">게임 가칭 · 용 잡으러 갑니다</p><p class="lead">__LOGLINE__</p><div class="actions"><a href="#battle-preview">새 전투 시안 보기</a><a href="#route">용에게 가는 길</a></div><p class="small" style="margin-top:20px">목표는 용과 싸워 이기고 길을 되찾는 것.<br>친근한 인물과 밝은 풍경 속에서 타이밍 전투의 도전성을 이어갑니다.</p></div><figure><a href="#unity-build"><img src="../../Evidence/Dragon-v5/dragon-v5-candidate-02/1280x720/fresh/v3-frame-v5-skill-on-contact-000326.png" width="1280" height="720" alt="실제 Unity 화면 · 루카의 바람 베기와 금빛 도트 파티클. candidate02에서 채택한 변경 없는 효과입니다."></a><figcaption>실제 Unity 화면 · 루카의 바람 베기와 금빛 도트 파티클. candidate02에서 채택한 변경 없는 효과입니다.</figcaption></figure></section>
<div class="stepbar" aria-label="기획 순서"><span><b>01 캐릭터를 정하고</b>종족·직업·목적·실루엣 정의</span><span><b>02 사건을 연결하고</b>출발 이유와 용을 쓰러뜨린 결과</span><span><b>03 길 위에 배치한다</b>5개 지역·50스테이지·보스 뒤 대사</span></div>
<details class="archive"><summary>이전 Unity 적용 기록 · v0.9.3</summary>__UNITY_V4__</details>__CHARACTER_SKILLS_V2__<details class="archive"><summary>이전 v0.9.3 대화 배치·만남</summary>__DIALOGUE_V4__</details>__GAME_IDENTITY_V2____STAGE_GROUND____ATTACK_AUDIO_V4__<details class="archive"><summary>이전 Unity 적용 기록 · v0.9.2</summary>__UNITY_V3__</details><details class="archive"><summary>이전 Unity 적용 기록 · v0.9.1 / v0.9.0</summary>__UNITY_V2____UNITY_V1__</details>__PIXEL_V3__<section id="monsters"><p class="eyebrow">LATEST · MONSTER PIXELS V2</p><h2>몬스터는 훨씬 큰 도트로.</h2><p class="lead">작은 비늘과 복잡한 명암을 줄이고, 사각 픽셀과 큰 색 덩어리로 다시 잡았습니다. 몬스터의 그래픽 밀도는 이 개정안을 기준으로 합니다.</p><figure class="wide"><a href="images/monster-pixel-v2.png"><img src="images/monster-pixel-v2.png" width="1536" height="1024" alt="위쪽 슬라임 뿔토끼 큰엄니 기블, 아래쪽 돌문 능선 와이번 브라크의 저해상도 도트 시안"></a><figcaption><div class="cast-legend"><b>위쪽</b><span>슬라임</span><span>뿔토끼</span><span>큰엄니</span><span>기블</span></div><div class="cast-legend"><b>아래쪽</b><span>돌문</span><span>능선 와이번</span><span>브라크</span></div>GPT로 재작성한 스타일 초안입니다. 기존 캐스트 원화보다 큰 픽셀·짧은 색 단계·단순한 장비 실루엣을 우선합니다.</figcaption></figure><div class="grid3"><article class="card"><h3>작은 몬스터</h3><p>일반 몬스터는 16~32 논리 픽셀, 중형은 48픽셀을 제작 기준으로 잡습니다. 눈·뿔·귀처럼 구별에 필요한 특징만 남깁니다.</p></article><article class="card"><h3>큰 보스</h3><p>보스는 64픽셀, 용은 최대96픽셀을 출발점으로 합니다. 같은 픽셀 단위에서 몸과 무기·날개의 덩어리를 키워 체급을 표현합니다.</p></article><article class="card"><h3>색과 명암</h3><p>개체당6~10색, 기본색과 그림자 중심의2단계 명암을 목표로 합니다. 작은 균열·털·금속광택·나무결은 최소화합니다.</p></article></div><p class="small">위 숫자는 정식 제작할 논리 캔버스 목표입니다. 생성 PNG가 해당 규격의 완성 스프라이트라는 뜻은 아닙니다. 일부 색면의 부드러운 농담과 픽셀 단위 차이, 돌문의 정면 자세는 실제 전투 자산 제작 때 정리합니다. 이 원화 자체는 콘셉트이며, 현재 게임용 도트와 구간별 적용 범위는 상단 Unity 제작 현황에서 확인합니다.</p><p><a href="monster-pixel-v2.json">도트 규격·GPT 프롬프트</a> · <a href="monster-pixel-review.md">아트 담당 검토</a></p></section><section id="cast"><p class="eyebrow">01 · CHARACTERS FIRST</p><h2>누구를 만나고, 누구와 싸울까?</h2><p class="lead">수인은 종족, 마법사는 직업입니다. 같은 종족도 역할이 다르고, 길에서 만나는 인물이 모두 적은 아닙니다.</p><figure class="wide"><a href="images/actors-pixel-v3.png"><img src="images/actors-pixel-v3.png" alt="평면 도트로 다시 만든 플레이어 루카와 NPC 토리 리나 바룬 도토"></a><figcaption>왼쪽부터 루카 · 토리 · 리나 · 바룬 · 도토. NPC는 v3, 몬스터는 위의 v2 시안을 기준으로 합니다. 현재 게임용 플레이어는 루카 Player-v3와 다렌·미엘 Player-v4를 사용합니다. <a href="images/cast-concept.png">이전 상세 원화는 정체성 참고로 보관합니다.</a></figcaption></figure><div class="cards">__CARDS__</div><details><summary>세계관의 종족과 직업 정의</summary><div class="scroll"><table><thead><tr><th>종족</th><th>외형 기준</th><th>이번 이야기의 범위</th></tr></thead><tbody>__TAXONOMY__</tbody></table></div><p style="margin-top:20px"><b>직업·역할:</b> __JOBS__</p><p class="small">돌문은 종족이 아닌 마법 구조물입니다. 엘프는 세계관 확장 후보로 남기며 이번 여정의 주역 수를 늘리지 않습니다.</p></details><p class="note"><b>플레이어는 루카·다렌·미엘입니다.</b> 현재 <a href="Adventure-v6/index.html#companions">여관 동료·전용 스킬·강화</a> 변경은 상단 v0.9.5 제작 현황에서 확인합니다. 새 계정의1~20 첫 만남은 토리·바룬이며 이전 계정의 리나·도토도 유지합니다. 모모는42스테이지 미발견 상태입니다.</p></section>
<section id="story"><p class="note">NPC 첫 만남·동행·여관 서비스는 <a href="Adventure-v5/index.html#journey">최신 v5안</a>이 우선합니다. 아래는 기존 이야기의 목표·지역 배경입니다.</p><p class="eyebrow">02 · A SMALL HEROIC ADVENTURE</p><h2>길을 막은 용, 길을 열러 가는 모험가.</h2><div class="grid2"><article class="card"><h3>첫 장면</h3><div class="script">__OPENING__</div></article><article class="card"><h3>모험의 끝</h3><div class="script">__ENDING__</div></article></div><div class="grid3" style="margin-top:24px"><article class="card"><h3>분명한 출발</h3><p>용이 산길을 차지해 수레가 오가지 못합니다. 의뢰를 맡은 모험가는 붉은 봉우리를 향해 떠납니다. 의뢰서와 멈춘 수레가 상황을 보여줍니다.</p></article><article class="card"><h3>길에서 만난 도움</h3><p>토리는 숲길을, 도토는 광산 통로를 알려줍니다. 리나는 여행 준비를 챙기고 바룬은 앞길을 막은 기블을 알려줍니다. 각자의 자리에서 필요한 한마디만 건넵니다.</p></article><article class="card"><h3>실제로 용을 이긴다</h3><p>Stage 50에서 브라크의 발톱·꼬리·불길을 읽고 싸워 승리합니다. 패배한 용이 빈 봉우리로 물러나면 수레길이 열립니다. 모험가는 의뢰를 완수하고 마을로 돌아옵니다.</p></article></div><p class="note">서사의 무게는 작은 모험에 두되 전투는 진지하게 만듭니다. 짧은 대사로 성격을 보여주고, 한 구역을 넘을 때마다 목적지에 가까워지는 변화를 남깁니다.</p></section>
<section id="route"><p class="eyebrow">03 · FROM MEADOW TO DRAGON</p><h2>숲을 지나, 산을 넘어, 용의 둥지로.</h2><figure class="wide"><a href="images/journey-concept.png"><img src="images/journey-concept.png" width="1672" height="941" alt="초원 숲 광산 고산 붉은 용의 둥지로 이어지는 5지역 배경 초안"></a><figcaption>지역별 색·구도 참고: 바람들판 → 솔바람숲 → 햇돌광산 → 구름고개 → 붉은바위둥지. 실제 제작 도트 밀도는 상단 v3 전투 시안이 우선하며, 나머지 구역도 같은 기준으로 제작합니다.</figcaption></figure><div class="route-tabs" role="tablist" aria-label="지역별 이야기">__TABS__</div>__ZONES__<noscript><p>탭을 보려면 JavaScript를 허용하세요. 전체 구역 내용은 <a href="story.json">스토리 데이터</a>에도 있습니다.</p></noscript><div class="flow" style="margin-top:26px"><span>보스 전투 승리</span><span>패배·퇴장 장면</span><span>짧은 대사</span><span>유물3택1</span><span>다음 지역</span></div><p class="small" style="margin-top:14px">NPC 대사 장면은 보스가 물러난 뒤 인물이 등장합니다. 브라크처럼 보스 본인이 말하는 장면은 대사 뒤 퇴장합니다. 마지막 구역은 보상·완주 저장 후 엔딩으로 이어집니다.</p></section>
<section id="stages"><p class="eyebrow">04 · STAGE ROSTER</p><h2>첫 10스테이지부터 만들 수 있는 편성</h2><p>바람들판은 슬라임·뿔토끼·멧돼지의 세 체형으로 시작합니다. 크기·장비·준비 자세를 달리해 패턴을 구분하고, 5스테이지의 큰뿔토끼와 10스테이지의 큰엄니에는 전용 동작을 만듭니다.</p>__MVP_TABLE__<h3 style="margin-top:34px">그다음 40스테이지</h3><p class="small">50개 편성은 11종의 기본 체형과 변형·전용 보스로 구성합니다. 색만 바꾸지 않고 실루엣이나 준비 동작도 달리합니다. 새 스프라이트 50종과 전체 애니메이션이 제작됐다는 뜻은 아닙니다.</p>__MORE_STAGES__<div class="grid2"><article class="card"><h3>보스 배치</h3><p>10 큰엄니 → 20 기블 → 30 돌문 → 40 능선 와이번 → 50 브라크.</p><p>야생의 힘, 방패와 창, 무거운 팔, 공중 공격, 용의 복합 패턴 순으로 위협이 커집니다.</p></article><article class="card"><h3>보상 규칙</h3><p>제작판은 기존 수치를 유지해 중간 보스 보석0개, 보스 보석4개입니다. 유물 후보3개 중1개는 도전 종료 정산에서 선택합니다. 보유 유물은 자동 적용하고 중복 획득으로 레벨을 올립니다. 지급량과 강화 수치를 이번 테마 개편에서 바꾸지 않습니다.</p></article></div></section>
<section id="design"><p class="eyebrow">05 · FANTASY ART & UI</p><h2>양피지, 가죽 장비, 맑은 들판.</h2><p>종을 중심으로 한 명칭과 장식은 새 모험에 맞춰 교체합니다. 머리·스카프·가방·한손검으로 읽히는 루카의 모험가 정체성은 이어가며, 장식은 지도·방패·검·보석으로 정리합니다.</p><figure class="wide"><a href="images/meadow-pixel-v3.png"><img src="images/meadow-pixel-v3.png" width="1672" height="941" alt="첫 지역의 전투 배경 초안, 넓고 평평한 길과 중앙이 비어 있는 초원"></a><figcaption>첫 전투 배경 초안. 캐릭터와 예고가 겹치는 중앙을 비우고, 이동 시 먼 산·들판·풀·땅을 서로 다른 속도로 움직입니다. 실제 레이어 분리는 다음 제작 단계입니다.</figcaption></figure><div class="palette">__PALETTE__</div><div class="ui-card" aria-label="여관 강화 화면 구조 시안"><div class="ui-top"><b>모험가 · 루카</b><span class="ui-wallet"><img class="ui-pixel-icon" src="images/ui-pixel-v4/coin-normal.png" alt="골드">1,240 <img class="ui-pixel-icon" src="images/ui-pixel-v4/gem-normal.png" alt="보석">16</span></div><div class="ui-body"><div class="ui-list">루카<br><span style="color:#63786e">검사</span></div><div><div class="ui-stats"><span class="chosen">공격력</span><span>체력</span><span>행운</span><span>기세</span><span>회복력</span></div><p style="font:30px Pixel;margin-top:24px">50 → 130</p><p style="font:18px Pixel">Lv.10 / Lv.11</p><div class="ui-quote"><span class="chosen">+1</span><span>최대</span></div></div></div><div class="ui-bottom"><span><img class="ui-pixel-icon" src="images/ui-pixel-v4/bag-normal.png" alt="">유물</span><span class="primary">강화 · 225 골드</span><span>Stage 11</span></div></div><p class="ui-label">여관 강화 화면의 구조 시안입니다. 재화·성장 값은 기존 예시이며 UI 버튼은 실행용 컨트롤이 아닙니다. 별도 캐릭터 선택·유물 상세·확인창의 흐름은 유지합니다.</p><div class="scroll"><table><thead><tr><th>이전 표기</th><th>새 제안</th><th>적용 의미</th></tr></thead><tbody>__RENAMES__</tbody></table></div><div class="grid2" style="margin-top:26px"><article class="card"><h3>전투에서 유지할 것</h3><p>위·뒤 회피와 아래 쳐내기, 대각선 베기, 달리기 전환, 큰 Stage 표시, 보스 줌·포효를 이어갑니다. 전투 HUD의 위치를 이어가고 체력바·방향키·검·방패·패널은 상단 UI v4 도트 규격으로 통일합니다.</p><p>위험은 산호색과 진한 외곽선, 성공은 청록색과 확산 도형으로 구분합니다.</p></article><article class="card"><h3>모션을 만들 때</h3><p>루카는 갈색 머리·붉은 스카프·초록 튜닉·검·가방을 전 프레임에서 유지합니다. 토리의 귀·꼬리, 리나의 모자·지팡이, 바룬의 큰 어깨·대검도 상태마다 바뀌지 않아야 합니다.</p><p>캐릭터 시트를 잘라 늘리는 작업으로 달리기·베기·피격이 완성됐다고 처리하지 않습니다.</p></article></div></section>
<section id="delivery"><p class="eyebrow">06 · PRODUCTION SCOPE</p><h2>현재 실행 범위와 다음 제작</h2><div class="grid3"><article class="card"><h3>현재 · 초원과 숲</h3><p>1~10 초원5체형, 11~20 고블린·숲송이10종. 루카·다렌·미엘의 모션과 20초 수동 스킬, 선명한 예고·기절바, 도트 UI를 연결했습니다.</p></article><article class="card"><h3>현재 · 흐름 연결</h3><p>새 실행판은 의뢰 시작→선택·강화→Stage1 튜토리얼→연속 전투입니다. 10보스 대사 후11로 이어지고,20은 대사 후MVP 완주입니다. 유물은 도전 종료 정산에서 선택합니다.</p></article><article class="card"><h3>기획 · 남은 여정</h3><p>21~50의 광산·고산·용 둥지 전투와 전용 지역 배경은 후속 제작입니다. 지면·등장 순서·보스 뒤 이야기를 먼저 정의했습니다.</p></article></div><p class="note"><b>기획50스테이지와 실행20스테이지를 구분합니다.</b> 플레이어 3명 원본156장(아래 쳐내기 포함198참조), 초원 원본120장, 숲30클립235샘플, 초상화10장, 동료5종15클립98프레임, 배경2개 레이어와 UI v4 아이콘45개가 현재 연결 범위입니다. 숲 바닥은 같은 지면 그림의 색조 구분이며,50개의 개별 바닥 원화나21~50 전투를 모두 제작한 것은 아닙니다. 동료5종 배우는 위의 현재 적용 범위에 포함됩니다. 게임명은 가칭이고 저장소 Last-Bell 이름은 유지합니다.</p><h3>담당 검토와 원본</h3><div class="files"><a href="cast.json">캐릭터 정의</a><a href="story.json">스토리·50스테이지</a><a href="stage-ground-v1.json">스테이지별 지면</a><a href="character-skills-v2.json">현재 전용 스킬 규칙</a><a href="#game-identity">현재 핵심 재미</a><a href="Production/Player-v3/style-grounding-review.md">플레이어 비교·접지</a><a href="Production/Forest-v1/independent-review.md">숲10종 독립 검토</a><a href="dragon-v3-plan-review.md">독립 기획 검토</a><a href="../../Production/dragon-v6-integration.json">현재 Unity 적용 기록</a><a href="validation.json">기획서 정적 검증</a></div><p class="small" style="margin-top:20px">기획·아트·Client·QA 담당이 병렬로 작업했습니다. GPT 시안과 실제 PixelLab 게임 원본을 구분하고, 최신 실행 검증 결과와 배포본은 상단 Unity 제작 현황에 기록합니다.</p></section></main><footer><a href="../../index.html">전체 기획서</a> · <a href="../../Presentation/index.html">전투 연출 기획</a> · <a href="../Bright-v1/index.html">이전 축제안 보관본</a><p>용 잡으러 갑니다 · Dragon v1 · 2026.10.24</p></footer></body></html>'''
tokens={'UNITY_V6':(B/'unity-v6-section.html').read_text(encoding='utf-8'),'UNITY_V5':(B/'unity-v5-section.html').read_text(encoding='utf-8').replace('id="unity-build"','id="unity-build-v5"'),'ADVENTURE_V5':(B/'adventure-v5-section.html').read_text(encoding='utf-8'),'UNITY_V4':(B/'unity-v4-section.html').read_text(encoding='utf-8').replace('id="unity-build"','id="unity-build-v4"'),'CHARACTER_SKILLS_V2':(B/'character-skills-v2-section.html').read_text(encoding='utf-8'),'DIALOGUE_V4':(B/'dialogue-v4-section.html').read_text(encoding='utf-8'),'GAME_IDENTITY_V2':(B/'dragon-identity-v2-section.html').read_text(encoding='utf-8'),'ATTACK_AUDIO_V4':(B/'attack-audio-v4-section.html').read_text(encoding='utf-8'),'ATTACK_AUDIO':(B/'attack-audio-section.html').read_text(encoding='utf-8'),'UNITY_V3':(B/'unity-v3-section.html').read_text(encoding='utf-8').replace('id="unity-build"','id="unity-build-v3"'),'CHARACTER_SKILLS':(B/'character-skills-section.html').read_text(encoding='utf-8'),'GAME_IDENTITY':(B/'dragon-identity-section.html').read_text(encoding='utf-8'),'STAGE_GROUND':(B/'stage-ground-section.html').read_text(encoding='utf-8'),'UNITY_V2':(B/'unity-v2-section.html').read_text(encoding='utf-8'),'UNITY_V1':(B/'unity-v1-section.html').read_text(encoding='utf-8'),'PIXEL_V3':(B/'pixel-v3-section.html').read_text(encoding='utf-8'),'PIXEL_UI_V4':(B/'pixel-ui-v4-section.html').read_text(encoding='utf-8'),'LOGLINE':e(S['logline']),'CARDS':cards,'TAXONOMY':taxonomy,'JOBS':job_text,'OPENING':paragraphs(S['opening']['sentences']),'ENDING':paragraphs(S['ending']['sentences']),'TABS':tabs,'ZONES':zones,'MVP_TABLE':stage_table(S['stages'][:10]),'MORE_STAGES':more,'PALETTE':palette,'RENAMES':renames}
for key,value in tokens.items():template=template.replace('__'+key+'__',value)
(B/'index.html').write_text(template,encoding='utf-8')
print(f'Built Dragon-v1 board: {len(C["coreCast"])} characters, 5 zones, 50 stages.')
